/* Demonstrates using writev to write data from two separate buffers (header and payload) to a file in a single system call. */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/uio.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>

int main() {
    const char *filepath = "writev_demo.txt";
    int fd = open(filepath, O_WRONLY | O_CREAT | O_TRUNC, 0644);

    if (fd == -1) {
        perror("open failed");
        return EXIT_FAILURE;
    }

    char header[] = "[DATA START]\n";
    char payload[] = "This payload follows the header immediately.\n";

    // 1. Define the vector elements
    struct iovec iov[2];

    // iov[0]: The header buffer
    iov[0].iov_base = header;
    iov[0].iov_len = strlen(header);

    // iov[1]: The payload buffer
    iov[1].iov_base = payload;
    iov[1].iov_len = strlen(payload);

    int iovcnt = 2;
    size_t total_requested = iov[0].iov_len + iov[1].iov_len;

    // 2. Perform the vector write
    ssize_t bytes_written = writev(fd, iov, iovcnt);

    if (bytes_written == -1) {
        perror("writev failed");
        close(fd);
        return EXIT_FAILURE;
    } else if (bytes_written < total_requested) {
        fprintf(stderr, "Warning: Short write occurred (%zd of %zd bytes).\n", bytes_written, total_requested);
    } else {
        printf("Successfully wrote %zd bytes using writev to %s.\n", bytes_written, filepath);
    }

    close(fd);
    return EXIT_SUCCESS;
}
